	void sieve(int n, int k, MI* f) {
		vector<int> p; fill_n(v + 1, n, 0), f[1] = 1;
		REP(i, 2, n) {
			if (!v[i]) p.pb(i), f[i] = qpow((MI)i, k);
			for (int j : p) {
				if (i * j <= n) f[i * j] = f[i] * f[j], v[i * j] = 1;
				if (i * j > n || i % j == 0) break;
