cint N=5e5,M=5e5,H=20;
int n,m;
int val[N+1];
int eu[M+1],ev[M+1],low[M+1],lim[M+1];
int tl[M+1],tr[M+1];
struct dx{
    int idx,val;
}c[M<<1|1];
struct edge{
    int u,v,l,r;
};
vector<edge>E,EL[H+1],ER[H+1];
struct info{
    int t,u;
}mdf[M+1];
int tag[N+(M<<2|1)],mx[N+(M<<2|1)];
int fa[N+(M<<2|1)];
int tot;
int top[N+(M<<2|1)];
int head[N+(M<<2|1)];
struct et{
