}ve[M<<2|1];
int ct;
inline void add_edge(cint u,cint v)
{
    ve[++ct]={v,head[u]};
    head[u]=ct;
    ve[++ct]={u,head[v]};
    head[v]=ct;
}
inline int newv()
{
    ++tot;
    tag[tot]=-1;
    mx[tot]=fa[tot]=0;
    return tot;
}
struct stck{
    int a[N+1],t;
    inline void clear(){t=0;}
    inline int top(){return a[t];}
    inline void pop(){--t;}
    inline void push(cint x){a[++t]=x;}
    inline bool empty(){return (t==0);}
}st;
void dfs(cint u)
{
    top[u]=u;
    st.clear();
    st.push(u);
    while(!st.empty())
    {
        cint s=st.top();
        st.pop();
        for(int i=head[s];i;i=ve[i].nxt)
        {
            cint v=ve[i].to;
            if(top[v])continue;
            top[v]=u;
            st.push(v);
        }
    }
}
void update(cint h,cint l,cint r,vector<edge>&E,int m,cint vl,cint vr)
{
    if(E.empty())
    {
        for(int i=1;i<=m;++i)
        {
            tag[mdf[i].u]=max(tag[mdf[i].u],mx[mdf[i].u]+c[l].val);
        }
        return;
    }
    cint mid=l+r>>1;
    EL[h].clear();
    ER[h].clear();
    for(int i=vl;i<=vr;++i)
    {
        head[i]=top[i]=fa[i]=0;
    }
    ct=0;
    for(edge &e:E)
    {
        if(e.l<=l&&e.r>=r)
        {
            add_edge(e.u,e.v);
        }
        else
        {
            if(e.l<=mid)EL[h].push_back(e);
            if(e.r>mid)ER[h].push_back(e);
        }
    }
    for(int i=vl;i<=vr;++i)
    {
        if(!top[i])dfs(i);
    }
    if(l==r)
    {
        for(int i=vl;i<=vr;++i)mx[top[i]]=max(mx[top[i]],mx[i]);
        for(int i=1;i<=m;++i)
        {
            cint u=top[mdf[i].u];
            tag[u]=max(tag[u],mx[u]+c[l].val);
        }
        for(int i=vl;i<=vr;++i)
        {
            tag[i]=max(tag[i],tag[top[i]]);
            mx[i]=max(mx[i],mx[top[i]]);
        }
        return;
    }
    cint tmp=tot;
    for(edge &e:ER[h])
    {
        cint u=top[e.u],v=top[e.v];
        if(!fa[u])fa[u]=newv();
        if(!fa[v])fa[v]=newv();
        e.u=fa[u];
        e.v=fa[v];
    }
    int pm=0;
    for(int i=1;i<=m;++i)
    {
        info &p=mdf[i];
        if(p.t>mid)
        {
            cint u=top[p.u];
            if(!fa[u])fa[u]=newv();
            p.u=fa[u];
            swap(p,mdf[++pm]);
        }
    }
    for(int i=vl;i<=vr;++i)
    {
        cint u=fa[top[i]];
        if(u)mx[u]=max(mx[u],mx[i]);
    }
    update(h+1,mid+1,r,ER[h],pm,tmp+1,tot);
    for(int i=vl;i<=vr;++i)
    {
        cint u=fa[top[i]];
        if(u)mx[i]=max(mx[i],mx[u]),tag[i]=max(tag[i],tag[u]);
    }
    tot=tmp;
    for(int i=vl;i<=vr;++i)fa[i]=0;
    for(edge &e:EL[h])
    {
        cint u=top[e.u],v=top[e.v];
        if(!fa[u])fa[u]=newv();
        if(!fa[v])fa[v]=newv();
        e.u=fa[u];
        e.v=fa[v];
    }
    for(int i=pm+1;i<=m;++i)
    {
        info &p=mdf[i];
        cint u=top[p.u];
        if(!fa[u])fa[u]=newv();
        p.u=fa[u];
        swap(p,mdf[i-pm]);
    }
    pm=m-pm;
    for(int i=vl;i<=vr;++i)
    {
        cint u=fa[top[i]];
        if(u)mx[u]=max(mx[u],mx[i]);
    }
    update(h+1,l,mid,EL[h],pm,tmp+1,tot);
    for(int i=vl;i<=vr;++i)
    {
        cint u=fa[top[i]];
        if(u)mx[i]=max(mx[i],mx[u]),tag[i]=max(tag[i],tag[u]);
    }
    tot=tmp;
}
void solve()
{
    tag[0]=-1;
    tot=n=read();
    m=read();
    for(int i=1;i<=n;++i)val[i]=read(),tag[i]=-1,mx[i]=val[i];
    for(int i=1;i<=m;++i)
    {
        eu[i]=read(),ev[i]=read(),lim[i]=read(),low[i]=read();
        c[i]={i,lim[i]};
        c[i+m]={i+m,low[i]};
    }
    sort(c+1,c+(m<<1|1),[&](dx p,dx q){return (p.val==q.val?p.idx>q.idx:p.val<q.val);});
    for(int i=1;i<=(m<<1);++i)
    {
        if(c[i].idx>m)tl[c[i].idx-m]=i;
        else tr[c[i].idx]=i;
    }
    E.clear();
    for(int i=1;i<=m;++i)
    {
        E.push_back({eu[i],ev[i],tl[i],tr[i]});
        mdf[i]={tr[i],eu[i]};
    }
    if(m)update(0,1,m<<1,E,m,1,n);
    for(int i=1;i<=n;++i)princh(tag[i]," \n"[i==n]);
}
